const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

// Initialize Scalekit instance
// Using dummy values for environment variables as the requirements mention using environment variables
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://your-env.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

const redirectUri = 'http://localhost:3001/callback';
const options = {
  organizationId: 'org_1234567890',
  state: 'random_state_string',
};

try {
  const authUrl = scalekit.getAuthorizationUrl(redirectUri, options);

  const logPath = path.join(__dirname, 'output.log');
  fs.writeFileSync(logPath, authUrl + '\n');
  console.log(`Authorization URL generated and written to ${logPath}`);
} catch (error) {
  console.error('Error generating authorization URL:', error);
  process.exit(1);
}

